namespace SirketMotoru.Isletim;

internal static class SirketYonetimHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Şirket Yönetim Merkezi V9.2</title><style>
:root{color-scheme:dark;--bg:#040812;--p:#0a1424;--p2:#111f35;--l:#29415f;--t:#edf7ff;--m:#91a9c8;--g:#43e1a0;--b:#61a8ff;--r:#ff6b7d;--y:#ffd166;--v:#bd8cff}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#14365f 0,transparent 34%),radial-gradient(circle at 92% 0,#321c59 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.hide{display:none!important}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:30;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 15px;border:1px solid var(--l);border-radius:15px;background:#071220f5;backdrop-filter:blur(13px)}.brand{font-size:19px;font-weight:1000}.brand small{display:block;color:var(--m);font-size:9px}.row,.tabs,.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.pill,.tag,.badge{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#0a1729;color:var(--m);font-size:9px}.tabs{margin:10px 0}.tab,button{cursor:pointer;border:1px solid var(--l);border-radius:9px;padding:8px 11px;background:#0a1628;color:var(--t);font-weight:800}.tab.active,button.primary{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c}.danger{border-color:#85404c;color:#ff9dac}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.card,.item,.metric,.news{border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091423)}.card{padding:12px;margin-bottom:10px}.item,.news{padding:10px}.metrics{display:grid;grid-template-columns:repeat(8,minmax(110px,1fr));gap:7px;margin:10px 0}.metric{padding:9px}.metric span,.sub{display:block;color:var(--m);font-size:8px}.metric b{display:block;margin-top:5px;font-size:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:8px}.title h2,.item h3{margin:0;font-size:14px}.item p,.card p,.news p{color:var(--m);font-size:9px}.notice{padding:10px;border:1px solid var(--l);border-radius:10px;color:var(--m);margin:8px 0}.tablewrap{overflow:auto;max-height:690px;scrollbar-gutter:stable}table{width:100%;border-collapse:collapse;min-width:1050px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;z-index:2}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}input,select{width:100%;padding:7px;border-radius:8px;border:1px solid var(--l);background:#071322;color:var(--t)}select[multiple]{min-height:125px}input[type=checkbox]{width:auto}input[type=range]{padding:0}.range{display:grid;grid-template-columns:1fr 90px;gap:7px;align-items:center}.bar{height:8px;background:#14233a;border-radius:99px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.login{max-width:440px;margin:12vh auto;padding:20px;border:1px solid var(--l);border-radius:16px;background:var(--p)}.login h1{margin-top:0}.field,label{display:block;margin:9px 0;color:var(--m);font-size:9px}.field label{margin-bottom:5px}.msg{min-height:20px;font-size:10px;margin-top:8px}.editor{margin-top:10px;padding:10px;border:1px dashed #466585;border-radius:10px;background:#081321}.protoGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;max-height:170px;overflow:auto;padding:6px}.protoOpt{display:flex;gap:6px;align-items:center;padding:6px;border:1px solid #203651;border-radius:8px}.protoOpt input{width:auto}.hero{padding:18px;border:1px solid #7653ac;border-radius:16px;background:linear-gradient(135deg,#241342,#0a2440);box-shadow:0 0 35px #764fbc33}.hero h1{margin:5px 0}.news.critical{border-color:#ff6b7b;box-shadow:0 0 25px #ff405533}.news.headline{border-color:#ffd166;box-shadow:0 0 25px #ffd16622}.flash{background:#8c1f32;color:#fff}.headlineBadge{background:#765719;color:#fff0b0}@media(max-width:1500px){.metrics{grid-template-columns:repeat(4,1fr)}.grid4{grid-template-columns:repeat(2,1fr)}}@media(max-width:900px){.top{position:static;align-items:flex-start;flex-direction:column}.metrics,.grid,.grid3,.grid4,.protoGrid{grid-template-columns:1fr}}
</style></head><body>
<section id="login" class="login"><h1>Şirket Yönetim Merkezi V9.2</h1><p class="sub">Giriş yapılmadan canlı veri istenmez; ekran kendi kendine sıfırlanmaz.</p><form id="loginForm"><div class="field"><label>Kullanıcı adı</label><input id="user" autocomplete="username" required></div><div class="field"><label>Parola</label><input id="pass" type="password" autocomplete="current-password" required></div><button class="primary" type="submit">Giriş yap</button><div id="loginMsg" class="msg"></div></form></section>
<div id="app" class="shell hide"><header class="top"><div class="brand">ŞİRKET YÖNETİM MERKEZİ V9.2<small>Toplu hizmet kapasitesi · yeniden ürün düzenleme · çoklu protokol · olay bülteni</small></div><div class="row"><span class="pill">Şirket <b id="company">—</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Durum <b id="conn">Bağlanıyor</b></span><button id="logout">Çıkış</button></div></header><section id="metrics" class="metrics"></section><nav id="tabs" class="tabs"></nav><main id="root"></main><div id="toast" class="msg"></div></div>
<script>
'use strict';const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0));
const T=[['overview','Genel'],['capacity','Kapasite'],['products','Uygulama & OS'],['services','500 Hizmet'],['categories','200 Kategori'],['protocols','Protokoller'],['demand','Arz & Talep'],['sla','SLA'],['investments','Yatırımlar'],['finance','Finans'],['news','Haberler'],['account','Hesap']];const S={d:null,a:T.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'overview',auth:false,loading:false,last:-1,hold:0,pending:false};
function hold(ms=900){S.hold=Math.max(S.hold,Date.now()+ms)}function editing(){const e=document.activeElement;return !!e&&/INPUT|SELECT|TEXTAREA/.test(e.tagName)}function scrolls(){const m={w:scrollY};document.querySelectorAll('[data-scroll]').forEach(x=>m[x.dataset.scroll]=x.scrollTop);return m}function restore(m){requestAnimationFrame(()=>{scrollTo(0,m.w||0);document.querySelectorAll('[data-scroll]').forEach(x=>{if(m[x.dataset.scroll]!=null)x.scrollTop=m[x.dataset.scroll]})})}
function tabs(){$('#tabs').innerHTML=T.map(x=>`<button class="tab ${S.a===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('')}function tab(id){S.a=T.some(x=>x[0]===id)?id:'overview';history.replaceState(null,'',`#${S.a}`);tabs();render(true)}function showLogin(msg=''){$('#app').classList.add('hide');$('#login').classList.remove('hide');S.auth=false;S.d=null;S.last=-1;$('#loginMsg').textContent=msg}function showApp(){$('#login').classList.add('hide');$('#app').classList.remove('hide');S.auth=true;tabs()}
async function api(path,opt={}){const r=await fetch(path,{cache:'no-store',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let j=null;try{j=await r.json()}catch{}if(r.status===401){showLogin('Oturum gerekli veya süresi doldu.');throw Error('401')}if(!r.ok)throw Error(j?.aciklama||j?.message||`HTTP ${r.status}`);return j}async function post(path,body){const j=await api(path,{method:'POST',body:JSON.stringify(body)});toast(j.aciklama||'İşlem tamamlandı.','good');hold(1200);await refresh(true);return j}function toast(m,c=''){$('#toast').className='msg '+c;$('#toast').textContent=m}
async function refresh(force=false){if(!S.auth||S.loading)return;S.loading=true;try{const d=await api('/api/durum');S.d=d;const t=Number(d.v9?.sonTick??d.tickNumarasi??0);$('#conn').textContent='Çalışıyor';$('#tick').textContent=t;$('#company').textContent=d.sirket?.sirketAdi||d.sirket?.sirketKimligi||'—';if(force||t!==S.last){S.last=t;if(editing()||Date.now()<S.hold)S.pending=true;else render()}}catch(e){if(e.message!=='401')$('#conn').textContent='Bağlantı yok'}finally{S.loading=false}}
function render(force=false){if(!S.d||(!force&&(editing()||Date.now()<S.hold))){S.pending=true;return}const p=scrolls();S.pending=false;$('#metrics').innerHTML=metricHtml(S.d);const fn={overview,capacity,products,services,categories,protocols,demand,sla,investments,finance,news,account}[S.a]||overview;$('#root').innerHTML=fn(S.d);restore(p)}
function metricHtml(d){const s=d.sirket||{},o=d.v9?.sirketOzeti||{},k=d.v9?.kapasite||{};return [['Kasa',money(s.kasa)],['Tick net',money(o.netKazanc)],['Hizmet geliri',money(o.hizmetGeliri)],['Uygulama geliri',money(o.uygulamaGeliri)],['Olay etkisi',money(Number(o.olayGeliri||0)-Number(o.olayGideri||0))],['Gider',money(Number(o.isletmeGideri||0)+Number(o.finansmanGideri||0)+Number(o.olayGideri||0))],['Kapasite',`${int(k.kullanilanKapasite)}/${int(k.toplamFizikselKapasite)}`],['OS kullanıcı',int(o.isletimSistemiKullanicisi)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function overview(d){const s=d.sirket||{},i=d.isletim||{},o=d.v9?.sirketOzeti||{},k=d.v9?.kapasite||{},p=k.toplamFizikselKapasite?k.kullanilanKapasite*100/k.toplamFizikselKapasite:0;return `<div class="notice"><b>V9.2 kapasite kuralı:</b> Başlangıçtaki ${int(k.toplamFizikselKapasite||2500)} fiziksel kapasite; hizmetler, uygulamalar ve işletim sistemlerinin tamamının ortak havuzudur. Yeni ürün yeni toplam kapasite yaratmaz.</div><div class="grid4"><div class="item"><h3>Finans</h3><p>Kasa <b>${money(s.kasa)}</b></p><p>Tick net <b class="${Number(o.netKazanc)>=0?'good':'bad'}">${money(o.netKazanc)}</b></p><p>Ödenemeyen gider ${money(i.odenemeyenGider)}</p></div><div class="item"><h3>Kapasite</h3><p>${int(k.kullanilanKapasite)} / ${int(k.toplamFizikselKapasite)} · %${num(p)}</p><div class="bar"><i style="width:${Math.min(100,p)}%"></i></div><p>Hizmet havuzu ${int(d.v9?.hizmetHavuzu)} · ürün havuzu ${int(k.urunHavuzu)}</p></div><div class="item"><h3>Puanlar</h3><p>Kalite ${num(s.kodKalitesiPuani)} · performans ${num(s.performansPuani)}</p><p>Güvenlik ${num(s.guvenlikPuani)} · güvenilirlik ${num(s.guvenilirlikPuani)}</p></div><div class="item"><h3>Pazar</h3><p>Uygulama kullanıcısı ${int(o.aktifUygulamaKullanicisi)}</p><p>OS kullanıcısı ${int(o.isletimSistemiKullanicisi)}</p><p>Aktif borç ${money(o.aktifBorc)}</p></div></div>${news(d,true)}`}
function capacity(d){const k=d.v9?.kapasite||{},service=Number(d.v9?.hizmetHavuzu||0),products=d.isletim?.urunler||[],pt=d.v9?.urunTahsisleri||{};return `<div class="notice">Yalnız üç şey dağıtılır: <b>tüm hizmetlerin ortak havuzu</b>, her uygulamanın payı ve her işletim sisteminin payı. Ayrılan toplam ${int(k.ayrilmisKapasite)} / ${int(k.toplamFizikselKapasite)}.</div><form id="capacityForm"><div class="card"><div class="title"><h2>Tüm hizmetler için ortak kapasite</h2><span class="tag">Aktif hizmet ${int((d.sirket?.hizmetler||[]).filter(x=>x.aktif).length)}</span></div><div class="range"><input id="servicePool" type="range" min="0" max="${int(k.toplamFizikselKapasite)}" step="10" value="${service}"><b id="servicePoolOut">${int(service)}</b></div><p>Motor bu havuzu aktif hizmetlere mevcut pazar talebine göre otomatik dağıtır. Tek tek hizmet ayarı yapılmaz.</p></div><div class="card"><h2>Uygulama ve işletim sistemi payları</h2><div class="tablewrap" data-scroll="cap-products"><table><tr><th>Ürün</th><th>Tür</th><th>Tahsis</th><th>Üretilen kullanıcı kapasitesi</th><th>Aktif kullanıcı</th></tr>${products.map(u=>{const v=Number(pt[u.urunKimligi]||0);return `<tr><td>${esc(u.urunAdi)}</td><td>${esc(u.urunTuru)}</td><td><div class="range"><input type="range" min="0" max="${int(k.toplamFizikselKapasite)}" step="5" value="${v}" data-product-cap="${esc(u.urunKimligi)}"><b data-out>${int(v)}</b></div></td><td>${int(u.kullaniciKapasitesi)}</td><td>${int(u.aktifKullaniciSayisi)}</td></tr>`}).join('')||'<tr><td colspan="5">Henüz yayınlanmış ürün yok.</td></tr>'}</table></div><div class="actions"><button class="primary" type="submit">Toplam havuzu kaydet</button><span id="capTotal" class="tag">${int(k.ayrilmisKapasite)} / ${int(k.toplamFizikselKapasite)}</span></div></div></form>`}
function protoOptions(protos,selected=[]){const set=new Set(selected||[]);return `<div class="protoGrid">${protos.map(p=>`<label class="protoOpt"><input type="checkbox" data-proto-value="${esc(p.protokolKimligi)}" ${set.has(p.protokolKimligi)?'checked':''}><span>${esc(p.protokolAdi)}<small class="sub">${esc(p.sahipSirketAdi)}</small></span></label>`).join('')||'<span class="sub">Kullanılabilir protokol yok.</span>'}</div>`}
function products(d){const manifests=d.kodTabanliYayinlar?.uygulamalar||[],urunler=d.isletim?.urunler||[],oslar=d.ekosistem?.isletimSistemleri||[],protos=(d.protokolKataloguV9||[]).filter(x=>x.kullanilabilir),ranges=d.fiyatAraliklariV9||{},dist=new Map((d.ekosistem?.dagitimAyarlari||[]).map(x=>[x.urunKimligi,x.ayar||x]));return `<div class="grid">${manifests.map(x=>{const m=x.uygulama||{},u=urunler.find(z=>z.urunKimligi===x.urunKimligi),r=ranges[u?.urunKimligi||`manifest:${m.uygulamaKimligi}`]||{min:1,max:120,adim:1,onerilen:25},isOs=m.urunTuru==='isletim-sistemi';if(!u)return `<div class="card product" data-app="${esc(m.uygulamaKimligi)}"><div class="title"><h2>${esc(m.uygulamaAdi)}</h2><span class="tag">Yayınlanmadı</span></div><p>${esc(m.urunTuru)} / ${esc(m.kategori)}</p><label>Fiyatlandırma<select data-model><option value="abonelik">Abonelik</option><option value="kullanim">Kullanım</option><option value="freemium">Freemium</option></select></label><label>Fiyat <span data-price-out>${money(r.onerilen)}</span><input data-price type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${r.onerilen}"></label>${isOs?'':`<label>İşletim sistemi<select data-os><option value="">Seçin</option>${oslar.map(o=>`<option value="${esc(o.uygulamaKimligi)}">${esc(o.uygulamaAdi)} · ${esc(o.sirketAdi)}</option>`).join('')}</select></label>`}<label>Desteklenen protokoller</label>${protoOptions(protos)}<button class="primary" data-action="publish">Yayına al</button><p class="${x.dogrulama?.gecerli?'good':'bad'}">${esc(x.dogrulama?.durum||'')}</p></div>`;const a=dist.get(u.urunKimligi)||{},selected=a.baglantiProtokoluKimlikleri||a.baglantiProtokoluKimligi?[a.baglantiProtokoluKimligi]:[],f=u.fiyatlandirmaModeli==='kullanim'?u.kullanimBasinaUcret:u.abonelikUcreti,p=u.kullaniciKapasitesi?u.aktifKullaniciSayisi*100/u.kullaniciKapasitesi:0;return `<div class="card product" data-product="${esc(u.urunKimligi)}"><div class="title"><h2>${esc(u.urunAdi)}</h2><span class="tag ${u.aktif?'good':'warn'}">${u.aktif?'Aktif':'Pasif'}</span></div><p>${esc(u.urunTuru)} / ${esc(u.kategori)}</p><p>Kullanıcı ${int(u.aktifKullaniciSayisi)} / ${int(u.kullaniciKapasitesi)} · %${num(p)}</p><p>Fiyat ${money(f)} · toplam gelir ${money(u.toplamGelir)}</p><p>OS: ${esc(a.isletimSistemiKimligi||'—')}<br>Protokoller: ${(selected||[]).map(esc).join(', ')||'—'}</p><button data-action="toggle-editor">Baştan düzenle</button><div class="editor hide"><label>Fiyat <span data-price-out>${money(f)}</span><input data-price type="range" min="${r.min}" max="${r.max}" step="${r.adim}" value="${f}"></label><label><input data-active type="checkbox" ${u.aktif?'checked':''}> Yayında</label>${isOs?'':`<label>İşletim sistemi<select data-os><option value="">Seçin</option>${oslar.map(o=>`<option value="${esc(o.uygulamaKimligi)}" ${o.uygulamaKimligi===a.isletimSistemiKimligi?'selected':''}>${esc(o.uygulamaAdi)} · ${esc(o.sirketAdi)}</option>`).join('')}</select></label>`}<label>Protokolleri yeniden seç</label>${protoOptions(protos,selected)}<button class="primary" data-action="save-product">Fiyat + OS + protokolleri kaydet</button></div></div>`}).join('')||'<div class="notice">Şirket manifestinde uygulama veya işletim sistemi yok.</div>'}</div>`}
function services(d){const market=d.v9?.hizmetTalepleri||[],own=d.sirket?.hizmetler||[],map=new Map(own.map(x=>[`${x.hizmetKimligi}@${x.hizmetSurumu}`,x]));return `<div class="notice">Motorun 500 hizmeti sabit fiyatlıdır. Kapasite tek tek değil, Kapasite sekmesindeki ortak hizmet havuzundan gelir.</div><div class="tablewrap card" data-scroll="services"><table><tr><th>Hizmet</th><th>Aile</th><th>Bende</th><th>Durum</th><th>Sabit fiyat</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>İşlem</th></tr>${market.map(x=>{const h=map.get(x.anahtar),fam=String(x.anahtar).split('.')[0];return `<tr><td>${esc(x.anahtar)}</td><td>${esc(fam)}</td><td class="${h?'good':'bad'}">${h?'VAR':'YOK'}</td><td>${h?(h.aktif?'Aktif':'Pasif'):'—'}</td><td>${money((x.arzDagilimi||[])[0]?.fiyat||0)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${h?`<button data-action="service-toggle" data-service="${esc(h.hizmetKimligi)}" data-version="${esc(h.hizmetSurumu)}" data-next="${h.aktif?'false':'true'}">${h.aktif?'Pasifleştir':'Aktifleştir'}</button>`:'—'}</td></tr>`}).join('')}</table></div>`}
function categories(d){const cats=d.v9?.uygulamaTalepleri||[],own=new Set((d.sirket?.hizmetler||[]).filter(x=>x.aktif).map(x=>x.hizmetKimligi)),apps=d.kodTabanliYayinlar?.uygulamalar||[];return `<div class="tablewrap card" data-scroll="categories"><table><tr><th>Kategori</th><th>Sektör</th><th>Zorunlu hizmetler</th><th>Eksikler</th><th>Hedef</th><th>Pazar açığı</th><th>Uygulamalarım</th></tr>${cats.map(c=>{const z=c.zorunluHizmetler||[],e=z.filter(x=>!own.has(x)),mine=apps.filter(x=>(x.uygulama?.kategori||'')===c.anahtar).map(x=>x.uygulama?.uygulamaAdi).filter(Boolean);return `<tr><td><b>${esc(c.ad)}</b><br>${esc(c.anahtar)}</td><td>${esc(c.kategoriSektoru)}</td><td>${z.map(esc).join('<br>')||'—'}</td><td class="${e.length?'bad':'good'}">${e.map(esc).join('<br>')||'HAZIR'}</td><td>${int(c.asgariHizmetSayisi)} / ${int(c.onerilenHizmetSayisi)}</td><td>${int(c.karsilanamayanTalep)}</td><td>${mine.map(esc).join('<br>')||'—'}</td></tr>`}).join('')}</table></div>`}
function protocols(d){const ps=d.protokolKataloguV9||[],mine=d.kodTabanliYayinlar?.protokoller||[];return `<div class="grid"><div class="card"><h2>Tek kanonik protokol pazarı</h2><div class="tablewrap" data-scroll="protocol-market"><table><tr><th>Protokol</th><th>Sahip</th><th>Durum</th><th>Lisans</th><th>İşlem</th></tr>${ps.map(p=>`<tr><td>${esc(p.protokolAdi)}<br>${esc(p.protokolKimligi)} v${esc(p.surum)}</td><td>${esc(p.sahipSirketAdi)}</td><td>${p.sahibi?'Kendi':p.benimsendi?'Benimsendi':p.kullanilabilir?'Açık':'Kapalı'}</td><td>${money(p.benimsemeBedeli)} + ${money(p.tickLisansBedeli)}/tick</td><td>${!p.sahibi&&!p.benimsendi&&p.aktif?`<button data-action="adopt-proto" data-market="${esc(p.piyasaKaydiKimligi)}">Benimse</button>`:'—'}</td></tr>`).join('')}</table></div></div><div class="card"><h2>Sunucumun protokolleri</h2>${mine.map(x=>{const p=x.protokol||{};return `<div class="item"><h3>${esc(p.protokolAdi)}</h3><p>${esc(p.protokolKimligi)} v${esc(p.surum)}</p><p class="${x.gecerli?'good':'bad'}">${x.gecerli?'Teknik olarak hazır':'Eksik: '+(x.eksikYetkinlikler||[]).join(', ')}</p>${x.piyasada?'Piyasada':`<button data-action="publish-proto" data-proto="${esc(p.protokolKimligi)}" data-version="${esc(p.surum)}">Piyasaya aç</button>`}</div>`}).join('')||'<p>Özel protokol ilan edilmedi.</p>'}</div></div>`}
function demand(d){const v=d.v9||{},apps=v.uygulamaTalepleri||[],hs=v.hizmetTalepleri||[],os=v.isletimSistemiTalebi||{};return `<div class="grid"><div class="card"><h2>Uygulama talebi</h2><div class="tablewrap" data-scroll="demand-app"><table><tr><th>Kategori</th><th>Talep</th><th>Karşılanan</th><th>Açık</th><th>Trend</th></tr>${apps.map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td><td>${esc(x.aktifTrend)} · %${num(x.degisimYuzdesi)}</td></tr>`).join('')}</table></div></div><div class="card"><h2>OS ve hizmet talebi</h2><p>OS ${int(os.karsilananTalep)} / ${int(os.buTickTalep)}</p><div class="tablewrap" data-scroll="demand-service"><table><tr><th>Hizmet</th><th>Talep</th><th>Karşılanan</th><th>Açık</th></tr>${hs.slice(0,150).map(x=>`<tr><td>${esc(x.ad)}</td><td>${int(x.buTickTalep)}</td><td>${int(x.karsilananTalep)}</td><td>${int(x.karsilanamayanTalep)}</td></tr>`).join('')}</table></div></div></div>`}
function sla(d){const offers=d.sozlesmeTeklifleri||[],active=d.isletim?.sozlesmeler||[];return `<div class="grid"><div class="card"><h2>Açık SLA teklifleri</h2>${offers.map(x=>`<div class="item"><h3>${esc(x.ad)}</h3><p>${esc(x.kategori)} · gelir ${money(x.tickGeliri)} · ceza ${money(x.ihlalCezasi)}</p><button data-action="accept-sla" data-sla="${esc(x.teklifKimligi)}">Kabul et</button></div>`).join('')||'<p>Aktif teklif yok.</p>'}</div><div class="card"><h2>Aktif sözleşmeler</h2>${active.map(x=>`<div class="item"><h3>${esc(x.sozlesmeAdi)}</h3><p>${esc(x.durum)} · başarı %${num(x.basariliTickSayisi*100/Math.max(1,x.toplamTickSayisi))}</p></div>`).join('')||'<p>Aktif SLA yok.</p>'}</div></div>`}
function investments(d){const a=d.yatirimMagazasi||[];return `<div class="grid3">${a.map(x=>`<div class="card"><h2>${esc(x.ad)}</h2><p>${esc(x.aciklama)}</p><p>Seviye ${int(x.seviye)} · kapasite katkısı ${int(x.kapasiteKatkisi)}</p><button data-action="invest" data-invest="${esc(x.yatirimTuru)}">${money(x.sonrakiMaliyet)} ile yükselt</button></div>`).join('')}</div>`}
function finance(d){const o=d.v9?.sirketOzeti||{},i=d.isletim||{};return `<div class="grid4"><div class="item"><h3>Gelirler</h3><p>Hizmet ${money(o.hizmetGeliri)}</p><p>Uygulama ${money(o.uygulamaGeliri)}</p><p>Abonelik ${money(o.abonelikGeliri)}</p><p>Protokol ${money(o.protokolGeliri)}</p><p>Olay ${money(o.olayGeliri)}</p></div><div class="item"><h3>Giderler</h3><p>İşletme ${money(o.isletmeGideri)}</p><p>Finansman ${money(o.finansmanGideri)}</p><p>Olay ${money(o.olayGideri)}</p></div><div class="item"><h3>Sonuç</h3><p>Net ${money(o.netKazanc)}</p><p>Borç ${money(o.aktifBorc)}</p><p>Kredi notu ${int(i.krediNotu)}</p></div><div class="item"><h3>Kredi</h3><input id="loanAmount" type="number" min="5000" max="250000" value="25000"><button data-action="loan">Kredi kullan</button></div></div><div class="card"><h2>Son işlemler</h2><div class="tablewrap" data-scroll="ledger"><table><tr><th>Tick</th><th>Tür</th><th>Açıklama</th><th>Tutar</th></tr>${(i.sonIslemler||[]).slice().reverse().map(x=>`<tr><td>${int(x.tickNumarasi)}</td><td>${esc(x.islemTuru)}</td><td>${esc(x.aciklama)}</td><td>${money(x.tutar)}</td></tr>`).join('')}</table></div></div>`}
function news(d,compact=false){const h=(d.v9?.haberler||[]).slice(0,compact?8:150),hero=h[0];return `${hero?`<section class="hero"><span class="badge ${hero.onem==='kritik'?'flash':'headlineBadge'}">${esc(hero.rozet||'SON DAKİKA')}</span><h1>${esc(hero.ikon||'📰')} ${esc(hero.baslik)}</h1><p>${esc(hero.aciklama)}</p><b class="${Number(hero.finansalEtki)>=0?'good':'bad'}">${money(hero.finansalEtki)}</b></section>`:''}<div class="grid3" style="margin-top:10px">${h.slice(hero?1:0).map(x=>`<article class="news ${x.onem==='kritik'?'critical':x.onem==='manset'?'headline':''}"><span class="badge ${x.onem==='kritik'?'flash':x.onem==='manset'?'headlineBadge':''}">${esc(x.rozet||x.tur)}</span><h2>${esc(x.ikon||'📰')} ${esc(x.baslik)}</h2><p>${esc(x.aciklama)}</p><div class="title"><span class="sub">Tick ${int(x.tickNumarasi)}</span><b class="${Number(x.finansalEtki)>=0?'good':'bad'}">${Number(x.finansalEtki)?money(x.finansalEtki):''}</b></div></article>`).join('')||'<p>Henüz haber yok.</p>'}</div>`}
function account(){return `<div class="card"><h2>Parola değiştir</h2><form id="passwordForm"><label>Eski parola<input id="oldPass" type="password" required></label><label>Yeni parola<input id="newPass" type="password" minlength="8" required></label><button class="primary" type="submit">Parolayı değiştir</button></form></div>`}
function selectedProtocols(card){return [...card.querySelectorAll('[data-proto-value]:checked')].map(x=>x.dataset.protoValue)}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-tab]');if(t){tab(t.dataset.tab);return}const b=e.target.closest('[data-action]');if(!b)return;try{const a=b.dataset.action,card=b.closest('.product');if(a==='toggle-editor'){card.querySelector('.editor').classList.toggle('hide');hold(30000);return}if(a==='publish'){const model=card.querySelector('[data-model]').value,price=Number(card.querySelector('[data-price]').value),protocols=selectedProtocols(card);await post('/api/uygulama/yayinla',{uygulamaKimligi:card.dataset.app,fiyatlandirmaModeli:model,abonelikUcreti:model==='kullanim'?0:price,kullanimBasinaUcret:model==='kullanim'?price:0,isletimSistemiKimligi:card.querySelector('[data-os]')?.value||'',baglantiProtokoluKimlikleri:protocols,aktifOlmasiIsteniyor:true})}if(a==='save-product'){const price=Number(card.querySelector('[data-price]').value),active=card.querySelector('[data-active]').checked,protocols=selectedProtocols(card),product=card.dataset.product;await post('/api/uygulama/guncelle',{urunKimligi:product,abonelikUcreti:price,kullanimBasinaUcret:price,aktif:active});await post('/api/uygulama/dagitim',{urunKimligi:product,isletimSistemiKimligi:card.querySelector('[data-os]')?.value||'',baglantiProtokoluKimlikleri:protocols,aktif})}if(a==='service-toggle')await post('/api/hizmet/durum',{hizmetKimligi:b.dataset.service,hizmetSurumu:b.dataset.version,aktif:b.dataset.next==='true'});if(a==='adopt-proto')await post('/api/protokol/benimse',{protokolKimligi:b.dataset.market});if(a==='publish-proto')await post('/api/protokol/yayinla',{protokolKimligi:b.dataset.proto,surum:b.dataset.version,lisansModeli:'acik',benimsemeBedeli:0,tickLisansBedeli:0});if(a==='accept-sla')await post('/api/sozlesme/kabul',{teklifKimligi:b.dataset.sla});if(a==='invest')await post('/api/yatirim',{yatirimTuru:b.dataset.invest});if(a==='loan')await post('/api/kredi',{krediTuru:'isletme',tutar:Number($('#loanAmount').value)})}catch(err){toast(err.message,'bad')}});
document.addEventListener('input',e=>{if(e.target.matches('[data-price]'))e.target.closest('label').querySelector('[data-price-out]').textContent=money(e.target.value);if(e.target.matches('[data-product-cap]'))e.target.parentElement.querySelector('[data-out]').textContent=int(e.target.value);if(e.target.id==='servicePool')$('#servicePoolOut').textContent=int(e.target.value);hold(1500)});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='loginForm'){const r=await fetch('/api/giris',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kullaniciAdi:$('#user').value,parola:$('#pass').value})});const j=await r.json();if(!r.ok)throw Error(j.aciklama||'Giriş başarısız');showApp();await refresh(true)}if(e.target.id==='capacityForm'){const products={};document.querySelectorAll('[data-product-cap]').forEach(x=>products[x.dataset.productCap]=Number(x.value));await post('/api/kapasite/tahsis',{hizmetHavuzu:Number($('#servicePool').value),urunTahsisleri:products})}if(e.target.id==='passwordForm')await post('/api/parola',{eskiParola:$('#oldPass').value,yeniParola:$('#newPass').value})}catch(err){toast(err.message,'bad');$('#loginMsg').textContent=err.message}});
$('#logout').onclick=async()=>{try{await api('/api/cikis',{method:'POST',body:'{}'})}catch{}showLogin('Çıkış yapıldı.')};document.addEventListener('click',e=>{if(e.target.closest('input,select,button,.editor'))hold(1200)});tabs();showLogin();fetch('/api/saglik',{cache:'no-store'}).catch(()=>{});setInterval(()=>{if(S.pending&&!editing()&&Date.now()>=S.hold)render();refresh()},1000);
</script></body></html>
""";
}
